(window.webpackJsonp=window.webpackJsonp||[]).push([[4],{361:function(t,e){"use strict";e.__esModule=!0,e.default={render:function(){return this.$createElement("div",{staticClass:"theme-default-content content__default lab-wide",domProps:{innerHTML:"\n<div class=\"lab-content\">\n<h1 id=\"成员\"><a href=\"#成员\" class=\"header-anchor\">#</a> 成员</h1>\n<section class=\"profile-hero\">\n  <div class=\"profile-photo\"><img src=\"/src/people/jiong%20zhang.jpg\" alt=\"张炯教授\"></div>\n  <div class=\"profile-intro\">\n    <p class=\"eyebrow\">课题组负责人</p>\n    <h2>张炯教授 <span>Jiong Zhang</span></h2>\n    <p class=\"profile-role\">南京大学生物医学工程学院长聘副教授<br>苏州校区</p>\n    <div class=\"profile-tags\"><span>IEEE 高级会员</span><span>MICCAI 会员</span><span>医学影像智能</span></div>\n    <div class=\"profile-actions\"><a class=\"button-primary\" href=\"mailto:jiong.zhang@ieee.org\">邮件联系</a><a href=\"https://scholar.google.com/citations?user=UJKsxKkAAAAJ&hl=en\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"button-secondary\">Google Scholar</a><a href=\"https://people.ucas.ac.cn/~jiong.zhang\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"button-secondary\">UCAS 主页</a></div>\n  </div>\n</section>\n\n<section class=\"profile-stats\" aria-label=\"学术概览\">\n  <div><strong>80+</strong><span>篇同行评议论文</span></div>\n  <div><strong>4</strong><span>个期刊编委职位</span></div>\n  <div><strong>3</strong><span>大研究主线</span></div>\n</section>\n\n<h2 id=\"学术简介\"><a href=\"#学术简介\" class=\"header-anchor\">#</a> 学术简介</h2>\n<p class=\"lead-copy\">张炯教授主要研究面向医学影像的人工智能、几何分析与形状分析方法，覆盖影像增强、分割、配准和疾病标志物提取，重点关注眼、脑及其他器官的血管与小血管疾病，推动方法创新与临床影像标志物研究相结合。</p>\n<p>加入南京大学前，张炯教授曾任中国科学院教授。2017 年获荷兰埃因霍温理工大学（TU/e）IMAG/e 团队博士学位，随后在 TU/e 开展博士后研究；2018 年赴美国南加州大学凯克医学院神经影像实验室继续博士后研究。</p>\n\n<h2 id=\"研究方向\"><a href=\"#研究方向\" class=\"header-anchor\">#</a> 研究方向</h2>\n<div class=\"focus-grid\">\n  <article class=\"focus-card\"><span class=\"card-index\">01</span><h3>医学影像智能</h3><p>医学影像增强、病灶分割与检测、图像配准、基础模型、多模态学习与医学智能体。</p></article>\n  <article class=\"focus-card\"><span class=\"card-index\">02</span><h3>血管影像分析</h3><p>二维与三维视网膜微血管分割、神经血管影像分析，以及定量血管影像标志物提取。</p></article>\n  <article class=\"focus-card\"><span class=\"card-index\">03</span><h3>几何与形状分析</h3><p>血管和皮层表面重建、拓扑感知建模、内蕴几何分析及可解释形态表征。</p></article>\n  <article class=\"focus-card\"><span class=\"card-index\">04</span><h3>临床转化</h3><p>脑血管与小血管疾病、糖尿病视网膜与神经病变、AMD、青光眼、阿尔茨海默病、缺血性卒中及烟雾病。</p></article>\n</div>\n\n<div class=\"modality-band\"><div><span>脑影像</span><strong>MRI · MRA · CTA · DSA</strong></div><div><span>眼科影像</span><strong>OCT · OCTA · 眼底 · UWF · FA · AS-OCT · 共聚焦显微影像</strong></div></div>\n\n<h2 id=\"学术经历\"><a href=\"#学术经历\" class=\"header-anchor\">#</a> 学术经历</h2>\n<div class=\"timeline\">\n  <div class=\"timeline-item\"><span>现任</span><div><h3>南京大学</h3><p>生物医学工程学院长聘副教授，苏州校区。</p></div></div>\n  <div class=\"timeline-item\"><span>此前</span><div><h3>中国科学院</h3><p>教授，宁波。</p></div></div>\n  <div class=\"timeline-item\"><span>2018 起</span><div><h3>美国南加州大学</h3><p>凯克医学院神经影像实验室博士后研究。</p></div></div>\n  <div class=\"timeline-item\"><span>2017</span><div><h3>荷兰埃因霍温理工大学</h3><p>获 IMAG/e 团队博士学位，随后在 TU/e 开展博士后研究。</p></div></div>\n</div>\n\n<h2 id=\"学术服务\"><a href=\"#学术服务\" class=\"header-anchor\">#</a> 学术服务</h2>\n<div class=\"service-grid\">\n  <article><h3>期刊编委</h3><p>担任 <em>Pattern Recognition</em>、<em>IEEE Journal of Biomedical and Health Informatics</em>、<em>Medical Physics</em> 和 <em>BMJ Open Ophthalmology</em> 副主编或编委。</p></article>\n  <article><h3>学术组织</h3><p>组织 MICCAI SWITCH 2025 和 SWITCH+ 2026；曾任 MICCAI、ICASSP、AAAI、ICIMH、ICGIP、MICAD 等会议领域主席或程序委员会成员。</p></article>\n  <article><h3>专题专刊</h3><p>牵头医学影像基础模型、眼部评估与全身疾病、医学影像重建与分析深度学习等专题专刊。</p></article>\n</div>\n\n<h2 id=\"研究团队\"><a href=\"#研究团队\" class=\"header-anchor\">#</a> 研究团队</h2>\n<div class=\"team-callout\"><div><p class=\"eyebrow\">加入我们</p><h3>医学、影像与可信智能交叉融合</h3><p>MI² Lab 欢迎计算机、生物医学工程、医学影像、临床医学和生命科学背景的同学及合作者。</p></div><a class=\"button-primary\" href=\"/zh/join/\">查看招生信息</a></div>\n<p class=\"roster-note\">课题组其他成员信息将在名单确认后继续更新。</p>\n</div>"}})}}}}]);
